                    me->DespawnOrUnsummon();
                }
                break;
            }
            default:
                break;
        }
    }

   void UpdateAI(uint32 diff) override
   {
        if (thurayaActivateTimer)
        {
            if (thurayaActivateTimer <= diff)
            {
                thurayaActivateTimer = 0;
                DoAction(ACTION_ENCOUNTERS_SWITCH_BOSS);
            }
            else
                thurayaActivateTimer -= diff;
        }
   }
}

